import sys
from collections import defaultdict

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    adj = defaultdict(list)
    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    assignment = [0] * (n + 1)

    for i in range(1, n + 1):
        if assignment[i] == 0:
            stack = [i]
            assignment[i] = 1

            while stack:
                u = stack.pop()
                current_party = assignment[u]

                enemies_in_same_party = 0
                for v in adj[u]:
                    if assignment[v] == current_party:
                        enemies_in_same_party += 1

                if enemies_in_same_party > 1:
                    new_party = 3 - current_party
                    assignment[u] = new_party
                    stack.append(u)
                    for v in adj[u]:
                        if assignment[v] == 0:
                            assignment[v] = new_party
                            stack.append(v)
                        elif assignment[v] == new_party:
                            pass

                for v in adj[u]:
                    if assignment[v] == 0:
                        assignment[v] = current_party
                        stack.append(v)

    valid = True
    for i in range(1, n + 1):
        count = 0
        for j in adj[i]:
            if assignment[i] == assignment[j]:
                count += 1
        if count > 1:
            valid = False
            break

    if valid:
        res = []
        for i in range(1, n + 1):
            res.append(str(assignment[i]))
        print("".join(res))
    else:
        print("-1")

if __name__ == "__main__":
    solve()
